NEW_FILES = {'data/textos/sistema_solar_examen2.tsv': "# Examen 2 de comprension (parche-94): preguntas reales de uso (listas, recuentos, 'dime algo de', definicion por enumeracion). Informativo.\nSEMILLA: fabrica\nU: El Sol es una estrella.\t\nU: El Sol está en el centro del Sistema Solar.\t\nU: Los planetas giran alrededor del Sol.\t\nU: Mercurio es el planeta más cercano al Sol.\t\nU: Venus es el segundo planeta.\t\nU: La Tierra es el tercer planeta y tiene una luna.\t\nU: La Luna gira alrededor de la Tierra.\t\nU: Marte es un planeta rojo.\t\nU: Marte tiene dos lunas.\t\nU: Júpiter es el planeta más grande.\t\nU: Júpiter es un gigante gaseoso.\t\nU: Saturno tiene anillos.\t\nU: Urano y Neptuno son planetas helados.\t\nU: Plutón es un planeta enano.\t\nU: Los asteroides son rocas pequeñas.\t\nU: Los cometas están hechos de hielo y polvo.\t\nU: El Sistema Solar es el conjunto de planetas, asteroides, cometas y lunas que orbitan alrededor del Sol.\t\nU: ¿Cuántos planetas hay en el sistema solar?\t8\nU: ¿Cuáles son los planetas que conoces del sistema solar?\tMercurio\nU: ¿Cuáles son los planetas que conoces del sistema solar?\tNeptuno\nU: ¿Qué me puedes decir de Mercurio?\tcercano\nU: Háblame de Marte\trojo\nU: ¿Qué puedes contarme sobre Saturno?\tanillos\nU: Cuéntame algo sobre Plutón\tenano\nU: ¿Qué sabes acerca de Venus?\tsegundo\nU: ¿Qué planetas conoces?\tUrano\nU: Dime los planetas que sabes\tTierra\nU: ¿Cuántos planetas conoces?\t8\nU: ¿De qué se compone el Sistema Solar?\tcometas\nU: ¿Qué incluye el Sistema Solar?\tasteroides\nU: ¿Qué orbita alrededor del Sol?\tasteroides\nU: ¿Son pequeños los asteroides?\tSí\nU: ¿Qué son los asteroides?\trocas\n", 'tests/test_parche94.py': '"""parche-94: listas y recuentos de una clase, \'dime algo de X\', definicion por enumeracion, asteroides."""\nimport os\nimport tempfile\n\nfrom src.language.consultas import canonical\nfrom src.language.qa import QA\nfrom src.language.school_parser import SchoolParser\nfrom src.memory.store import MemoryStore\nfrom src.reasoning.lessons import canon\n\n\ndef _qa(facts, display=None):\n    mem = MemoryStore(os.path.join(tempfile.mkdtemp(), "m.json"))\n    for f in facts:\n        mem.add_fact(f)\n    mem.display.update(display or {})\n    return QA(mem, lambda s: [], lambda fs: [])\n\n\ndef test_dime_algo_de():\n    for q in ("¿Qué me puedes decir de Mercurio?", "Háblame de Mercurio", "Cuéntame algo sobre Mercurio", "¿Qué información tienes sobre Mercurio?"):\n        assert canonical(q) == "¿Qué sabes de Mercurio?", q\n    assert canonical("Dime los planetas que sabes") == "¿Cuáles son los planetas que conoces?"\n    assert canonical("Dime que Ana compra pan") == "Dime que Ana compra pan"\n\n\ndef test_lista_y_recuento():\n    qa = _qa([("MERCURIO", "es", "planeta"), ("VENUS", "es", "planeta"), ("TIERRA", "es", "planeta"), ("PLUTON", "es", "gigante")], {"TIERRA": "la Tierra", "PLANETA": "un planeta"})\n    assert qa.special("¿Cuántos planetas hay en el sistema solar?") == "Conozco 3 planetas: Mercurio, Venus y la Tierra."\n    assert qa.special("¿Cuáles son los planetas que conoces?").startswith("Los planetas que conozco son: Mercurio, Venus y la Tierra")\n    assert qa.special("¿Qué planetas conoces?") is not None\n    assert not (qa.special("¿Cuántos unicornios hay?") or "").startswith("Conozco")\n\n\ndef test_definicion_por_enumeracion():\n    p = SchoolParser.__new__(SchoolParser)\n    p.parse = lambda s, topic=None, verbs=None: [{"s": "planetas", "p": "orbitar_alrededor_de", "o": "sol", "neg": False}] if s.startswith("Los planetas") else []\n    got = SchoolParser.parse(p, "El Sistema Solar es el conjunto de planetas, asteroides, cometas y lunas que orbitan alrededor del Sol.")\n    objs = [(t["s"], t["p"], t["o"]) for t in got]\n    assert ("sistema_solar", "conjunto_de", "planetas") in objs and ("sistema_solar", "conjunto_de", "lunas") in objs and ("planetas", "orbitar_alrededor_de", "sol") in objs\n    qa = _qa([(t["s"], t["p"], t["o"]) for t in got if t["p"] == "conjunto_de"], {"SISTEMA_SOLAR": "el Sistema Solar"})\n    assert qa.special("¿De qué se compone el Sistema Solar?") == "El Sistema Solar está formado por planetas, asteroides, cometas y lunas."\n\n\ndef test_asteroides_singular():\n    assert canon("ASTEROIDES") == canon("ASTEROIDE") == "ASTEROIDE"\n    assert canon("CIUDADES") == "CIUDAD" and canon("PLANETAS") == "PLANETA"\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-94 instalado. Copias en {bk}" if plan else "parche-94: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

